import pulp

# Define the problem
prob = pulp.LpProblem("Maximize_{{OBJECTIVE_NAME}}", pulp.LpMaximize)

# Define decision variables
x = pulp.LpVariable('x', lowBound=0, cat='Integer')  # {{VARIABLE_DESCRIPTION_1}}
y = pulp.LpVariable('y', lowBound=0, cat='Integer')  # {{VARIABLE_DESCRIPTION_2}}
z = pulp.LpVariable('z', lowBound=0, cat='Integer')  # {{VARIABLE_DESCRIPTION_3}}

# Objective function: maximize total {{OBJECTIVE_TYPE}}
prob += {{COEFFICIENT_1}} * x + {{COEFFICIENT_2}} * y + {{COEFFICIENT_3}} * z

# Constraints
# Budget constraint
prob += {{COST_1}} * x + {{COST_2}} * y + {{COST_3}} * z <= {{BUDGET_LIMIT}}

# {{CONSTRAINT_DESCRIPTION_1}}
prob += y <= {{MAX_TRAIN_ADS}}

# {{CONSTRAINT_DESCRIPTION_2}}: At most a third of ads in water parks
prob += 2 * z - x - y <= 0

# {{CONSTRAINT_DESCRIPTION_3}}: Minimum 10% of ads in grocery stores
prob += 9 * x - y - z >= 0

# Solve the problem
prob.solve(pulp.PULP_CBC_CMD(msg=0))

# Print the optimal objective value
print(f"Answer: {round(pulp.value(prob.objective), 6)}")
